-- Payments bounded context: payments, their gateway transactions and issued receipts.
-- Identifiers are UUID strings generated by the context.

CREATE TABLE payment_payments (
    id                    VARCHAR(36)   NOT NULL,
    rancher_id            VARCHAR(36)   NOT NULL,
    appointment_id        VARCHAR(36),
    concept               VARCHAR(200)  NOT NULL,
    amount                DECIMAL(12,2) NOT NULL,
    currency              VARCHAR(3)    NOT NULL,
    status                ENUM ('CANCELLED', 'FAILED', 'PAID', 'PENDING') NOT NULL,
    payment_method_brand  VARCHAR(20),
    payment_method_last4  VARCHAR(4),
    payment_method_holder VARCHAR(160),
    created_at            DATETIME(6)   NOT NULL,
    confirmed_at          DATETIME(6),
    cancelled_at          DATETIME(6),
    PRIMARY KEY (id)
);

CREATE INDEX idx_payment_payment_rancher ON payment_payments (rancher_id);
CREATE INDEX idx_payment_payment_created_at ON payment_payments (created_at);

CREATE TABLE payment_transactions (
    id                 VARCHAR(36)  NOT NULL,
    payment_id         VARCHAR(36)  NOT NULL,
    provider           VARCHAR(60)  NOT NULL,
    provider_reference VARCHAR(120),
    status             ENUM ('APPROVED', 'DECLINED', 'PENDING') NOT NULL,
    failure_reason     VARCHAR(500),
    attempted_at       DATETIME(6)  NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX idx_payment_transaction_payment ON payment_transactions (payment_id);

CREATE TABLE payment_receipts (
    id             VARCHAR(36)  NOT NULL,
    payment_id     VARCHAR(36)  NOT NULL,
    receipt_number VARCHAR(40)  NOT NULL,
    document_url   VARCHAR(500) NOT NULL,
    issued_at      DATETIME(6)  NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_payment_receipt_number UNIQUE (receipt_number)
);

CREATE INDEX idx_payment_receipt_payment ON payment_receipts (payment_id);
